import json
J=json.load(open('/mnt/c/WSL/davita/translations/jobs_sid1.json'))
L={'Dough':'Adonan','Filling':'Isian','For boiling the tripe':'Untuk merebus babat','For brushing and serving':'Untuk olesan dan penyajian','For cooking and serving':'Untuk memasak dan penyajian','For rubbing':'Untuk bumbu lumur','For the aseeda':'Untuk aseeda','For the balool (broth)':'Untuk balool (kuah kaldu)','For the basil ghee':'Untuk ghee kemangi','For the batter':'Untuk adonan cair','For the broth':'Untuk kaldu','For the broth and chicken':'Untuk kaldu dan ayam','For the broth and meat':'Untuk kaldu dan daging','For the chicken':'Untuk ayam','For the chickpeas':'Untuk kacang arab (buncis kabuli)','For the cooking liquid':'Untuk cairan masak','For the daghabees':'Untuk daghabees','For the dagoos (salsa)':'Untuk dagoos (salsa)','For the dough':'Untuk adonan','For the dressing':'Untuk dressing','For the filling':'Untuk isian','For the fish':'Untuk ikan','For the garlic fry':'Untuk tumisan bawang putih','For the garlic yoghurt':'Untuk yogurt bawang putih','For the hareis':'Untuk hareis','For the hot sauce':'Untuk saus pedas','For the kishna':'Untuk kishna','For the kishna topping':'Untuk taburan kishna','For the lamb':'Untuk daging domba','For the layers':'Untuk lapisan','For the lemon-chilli dip':'Untuk saus celup lemon-cabai','For the loaf':'Untuk roti','For the ma\'soub':"Untuk ma'soub",'For the marag':'Untuk marag','For the maraheef':'Untuk maraheef','For the marasee':'Untuk marasee','For the meat':'Untuk daging','For the muqalqal':'Untuk muqalqal','For the pickle salad':'Untuk salad acar','For the qursan bread':'Untuk roti qursan','For the red sauce':'Untuk saus merah','For the rice':'Untuk nasi','For the rice and pasta':'Untuk nasi dan pasta','For the rice and topping':'Untuk nasi dan taburan','For the salad':'Untuk salad','For the salt pot':'Untuk panci garam','For the sour lahoh':'Untuk lahoh asam','For the stew':'Untuk semur','For the stock':'Untuk kaldu','For the stuffing':'Untuk isian','For the sulat':'Untuk sulat','For the syrup':'Untuk sirop','For the topping':'Untuk taburan','For the topping and smoking':'Untuk taburan dan pengasapan','For the vegetables':'Untuk sayuran','For the wheat bread':'Untuk roti gandum','For the yoghurt sauce':'Untuk saus yogurt','Meat and marinade':'Daging dan marinasi','Rice':'Nasi','To brown the meat':'Untuk menumis daging','To garnish':'Untuk hiasan','To garnish and serve':'Untuk hiasan dan penyajian','To serve':'Untuk penyajian'}
def build(start,recs,out):
    res=[]
    for n,(t,d,p,s,ing,st,h) in enumerate(recs):
        j=J[start+n]
        def pr(k,L2):
            src=j[k]
            assert len(src)==len(L2),(j['id'],k,len(src),len(L2))
            return [[(L[g] if g else None),x] for (g,_),x in zip(src,L2)]
        res.append({"id":j['id'],"translations":{"id":{"title":t,"description":d,"portions":p,"serving_size":s,"ingredients":pr('ingredients',ing),"steps":pr('steps',st),"hints":pr('hints',h),"food_choices":[]}}})
    json.dump(res,open(out,'w',encoding='utf-8'),ensure_ascii=False,indent=1)
